import * as THREE from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  color,
  float,
  textureNode,
  mix,
  vec2,
  uv,
  mul,
  add,
} from 'three/tsl';
import { gsap } from 'gsap';
import { parallaxScroll } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  // Root group
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  root.rotation.set(0, 0, 0);
  root.userData.handlers = {};
  const timelines = [];

  // Load texture (same for all cards – distinct variants could be handled elsewhere)
  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');

  // Card parameters
  const CARD_WIDTH = 1.6;
  const CARD_HEIGHT = 1.0;
  const BEVEL_THICK = 0.025;
  const PITCH = 1.85;
  const CARD_COUNT = 5;
  const FOCUS_INDEX = Math.floor(CARD_COUNT / 2); // 2 (zero‑based)

  // Colors (hex)
  const COLORS = {
    background: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  // Helper to create a card (plane + bevel)
  function createCard(index) {
    const cardGroup = new THREE.Group();

    // Outer bevel plane
    const bevelGeom = new THREE.PlaneGeometry(
      CARD_WIDTH + BEVEL_THICK * 2,
      CARD_HEIGHT + BEVEL_THICK * 2
    );
    const bevelMat = new MeshBasicNodeMaterial();
    bevelMat.colorNode = color(COLORS.ink);
    const bevelMesh = new THREE.Mesh(bevelGeom, bevelMat);
    bevelMesh.position.set(0, 0, -0.001); // slightly behind inner plane
    cardGroup.add(bevelMesh);

    // Inner textured plane
    const innerGeom = new THREE.PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
    const innerMat = new MeshStandardNodeMaterial();
    innerMat.colorNode = color(COLORS.paper);
    innerMat.roughnessNode = float(0.55);
    innerMat.metalnessNode = float(0.2);
    innerMat.clearcoatNode = float(0.15);
    innerMat.mapNode = textureNode(baseTexture);
    innerMat.transparent = true;
    const innerMesh = new THREE.Mesh(innerGeom, innerMat);
    cardGroup.add(innerMesh);

    // Store references for cleanup / animation
    cardGroup.userData = {
      index,
      innerMat,
      bevelMat,
      innerMesh,
    };

    // Position along x
    const xPos = (index - FOCUS_INDEX) * PITCH;
    cardGroup.position.set(xPos, 0, 0);

    // Rotation: whole strip will be rotated later; add counter‑rotation for focus card
    if (index === FOCUS_INDEX) {
      // Counter‑rotate to face camera
      cardGroup.rotation.y = THREE.MathUtils.degToRad(18);
      // Underline bar
      const underlineGeom = new THREE.PlaneGeometry(CARD_WIDTH, 0.035);
      const underlineMat = new MeshStandardNodeMaterial();
      underlineMat.colorNode = color(COLORS.accent);
      underlineMat.emissiveNode = color(COLORS.accent);
      underlineMat.emissiveIntensityNode = float(1.3);
      underlineMat.roughnessNode = float(0.5);
      underlineMat.metalnessNode = float(0);
      const underlineMesh = new THREE.Mesh(underlineGeom, underlineMat);
      underlineMesh.position.set(0, -CARD_HEIGHT / 2 - 0.0175, 0.001);
      cardGroup.add(underlineMesh);
      cardGroup.userData.underlineMat = underlineMat;
    }

    // Scale & opacity based on distance from focus
    const dist = Math.abs(index - FOCUS_INDEX);
    const scaleFactor = index === FOCUS_INDEX ? 1.0 : 0.92;
    const opacity = 1 - (dist / (CARD_COUNT - 1)) * (1 - 0.55);
    cardGroup.scale.setScalar(scaleFactor);
    innerMat.opacityNode = float(opacity);

    // Caption text under each card
    const captions = [
      'NA-01 MERIDIAN',
      'NA-02 NOCTURNE',
      'NA-03 SIGNAL',
      'NA-04 VANTAGE',
      'NA-05 ARCHIVE',
    ];
    const captionText = captions[index];
    const captionMesh = createText(ctx.fontAtlas, {
      text: captionText,
      fontFamily: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 700,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: COLORS.ink,
    });
    captionMesh.position.set(0, -CARD_HEIGHT / 2 - 0.08, 0.002);
    captionMesh.scale.set(0.1, 0.1, 0.1); // scale down to scene units
    cardGroup.add(captionMesh);

    return cardGroup;
  }

  // Build cards
  const cards = [];
  for (let i = 0; i < CARD_COUNT; i++) {
    const card = createCard(i);
    cards.push(card);
    root.add(card);
  }

  // Rotate whole strip -18° on Y
  root.rotation.y = THREE.MathUtils.degToRad(-18);

  // Headline text
  const headline = createText(ctx.fontAtlas, {
    text: 'The collection',
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: COLORS.ink,
  });
  headline.position.set(-2.6, 1.5, 0);
  headline.scale.set(0.1, 0.1, 0.1);
  root.add(headline);

  // Body text
  const body = createText(ctx.fontAtlas, {
    text: 'Five calibres. One discipline.',
    fontFamily: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: COLORS.ink,
  });
  body.position.set(-2.6, -1.5, 0);
  body.scale.set(0.1, 0.1, 0.1);
  root.add(body);

  // Entrance animation (rise‑in + fade‑up)
  const entrance = gsap.timeline({ paused: true });
  entrance.from(
    root.position,
    {
      y: root.position.y + 0.4,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );
  entrance.from(
    root.scale,
    {
      y: 0.8,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );
  entrance.play();
  timelines.push(entrance);

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // Ensure the parallax‑scroll primitive is present (spec requirement)
  if (ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](root, { intensity: 0.5 });
  }

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose materials and textures
    for (const card of cards) {
      const { innerMat, bevelMat, underlineMat } = card.userData;
      innerMat.dispose();
      bevelMat.dispose();
      if (underlineMat) underlineMat.dispose();
    }
    baseTexture.dispose();

    // Kill GSAP timelines
    for (const tl of timelines) tl.kill();

    // Remove from parent if attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
